import {BUG_COLORS} from './refine-core.js';
import {BUDDY_GADGETS} from './buddy-core.js';
export function battleCue(m){const type=m.roundType;if(type==='reaction')return{title:m.phase==='go'?'GO · tap now':'WAIT · hands ready',detail:'Tap only when GO appears. Early taps lose points.'};if(type==='combo')return{title:m.clock<m.previewUntil?'Watch the sequence':'Repeat the sequence',detail:m.clock<m.previewUntil?'Remember the symbols in order.':`${m.seqIndex} / ${m.sequence.length} matched · choose the next symbol from memory`};if(m.learn&&m.question)return{title:m.question,detail:'Tap the correct answer. Avoid the other numbers.'};if(type==='accuracy'){const color=BUG_COLORS[m.targetColor];return{title:`Find ${color.name} ${color.mark}`,detail:'Match the requested color and symbol.'};}return{title:type==='survival'?`Stay in play · ${m.lives} lives`:type==='speed'?'Find the star · one target at a time':'Catch the moving star',detail:'Tap the star target; avoid distractions. Accuracy builds your streak.'};}
const hints={grab:'Grab a limb, move and release to fling. Add another finger to hold a different limb.',glove:'Tap near Pogo for a padded push.',spring:'Tap to place a spring launcher.',ball:'Tap to launch a bouncy ball toward Pogo or a ring.',water:'Tap to throw a water balloon.',foam:'Tap to fire a soft foam shot at a ring.',fan:'Place a fan near Pogo for a steady push.',magnet:'Place a magnet near Pogo to pull him toward it.',confetti:'Tap for a confetti burst.',slime:'Tap near Pogo for a sticky splat.',rocket:'Tap to launch Pogo with a cartoon rocket.',bubble:'Tap to lift Pogo in bubbles.',trampoline:'Place a trampoline under Pogo.',gravity:'Tap to switch the room’s gravity.',inflatable:'Tap to place an inflatable obstacle.'};
export function buddyStatus(m){const goal=m.mode==='sandbox'?'Sandbox · experiment freely':m.mode==='bounce'?`Impact chain ${m.bestCombo} / 8`:m.mode==='combo'?`${m.used.size} / 6 gadgets · ${m.hits} / 2 rings`:m.mode==='puzzle'?`${m.hits} / ${m.targets.length} rings · ${m.used.size} / 2 gadgets`:`${m.hits} / ${m.targets.length} rings${m.mode==='target'?' · use foam, balls or water':' · release all holds to score'}`;const tool=BUDDY_GADGETS.find(g=>g.id===m.tool);return `${goal} · ${tool?.name||'Grab'}: ${hints[m.tool]||'Tap the room to use this gadget.'}${m.clock<m.nextGadget?' Gadget cooling down.':''}`;}
export function drawPlayroom(c,m){const palette=m.room.id===1||m.room.id===6?['#263747','#405269']:m.room.id===5?['#234b53','#3c7576']:['#344657','#536c6d'];const g=c.createLinearGradient(0,0,0,640);g.addColorStop(0,palette[0]);g.addColorStop(1,palette[1]);c.fillStyle=g;c.fillRect(0,0,1000,640);for(let row=0;row<3;row++)for(let col=0;col<7;col++){c.fillStyle=(row+col)%2?'#9fb2a31a':'#c3b39112';c.beginPath();c.roundRect(8+col*144,95+row*160,132,146,18);c.fill();}for(const x of [120,830]){c.fillStyle='#152f3d';c.beginPath();c.roundRect(x,140,65,100,22);c.fill();c.strokeStyle='#a9c7bd66';c.lineWidth=5;c.stroke();c.fillStyle='#a4cbb43b';c.fillRect(x+12,155,41,9);}c.fillStyle='#243e48';c.fillRect(0,605,1000,35);c.strokeStyle='#8aa69c';c.lineWidth=3;c.beginPath();c.moveTo(0,605);c.lineTo(1000,605);c.stroke();}
export function drawBattleStage(c){const g=c.createLinearGradient(0,0,0,640);g.addColorStop(0,'#203341');g.addColorStop(1,'#303a53');c.fillStyle=g;c.fillRect(0,0,1000,640);c.strokeStyle='#a7bec121';c.lineWidth=3;for(const x of [55,945]){c.strokeRect(x-20,150,40,400);for(let y=170;y<540;y+=60){c.fillStyle='#91b1a52d';c.fillRect(x-9,y,18,25);}}c.strokeStyle='#c7b89422';c.lineWidth=8;c.beginPath();c.ellipse(500,390,380,170,0,0,Math.PI*2);c.stroke();c.fillStyle='#172c38';c.fillRect(0,605,1000,35);}
